//! Installed launcher execution must not be classified as an artifact edit.

use std::io::Write;
use std::process::{Command, Stdio};
use std::time::Duration;
use storyhook_test_support::{ChildGuard, scratch_dir};

fn check(command_text: &str, home: &std::path::Path) -> bool {
    let mut command = Command::new("bash");
    command
        .arg(concat!(env!("CARGO_MANIFEST_DIR"), "/plugins/story/hooks/protect-install.sh"))
        .env("HOME", home)
        .env("STORYHOOK_DATA_DIR", home.join("data"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    let mut child = ChildGuard::spawn_with_output(&mut command).expect("start tracked hook");
    write!(child.stdin().expect("stdin"), "{}", serde_json::json!({
        "tool_name":"Bash", "tool_input":{"command":command_text}
    })).expect("send hook payload");
    let result = child.wait_with_output_within(
        Duration::from_secs(2 * storyhook::daemon::lifecycle::SPAWN_DEADLINE.as_secs()),
        || "launcher protection hook timed out".into(),
    );
    assert!(result.status.success(), "{:?}", result);
    let value: serde_json::Value = serde_json::from_slice(&result.stdout).expect("hook JSON");
    value.pointer("/hookSpecificOutput/permissionDecision").and_then(|v| v.as_str()) != Some("deny")
}

#[test]
fn exact_launcher_execution_is_allowed_but_artifact_mutations_are_not() {
    let temp = scratch_dir();
    let home = temp.path().join("home with spaces");
    let managed = home.join(".codex/storyhook");
    std::fs::create_dir_all(home.join("data")).unwrap();
    std::fs::create_dir_all(&managed).unwrap();
    std::fs::write(home.join("data/managed-paths"), format!("{}\n", managed.display())).unwrap();
    let launcher = managed.join("story.sh");
    std::fs::write(&launcher, "#!/usr/bin/env bash\nexec story plugin run codex -- \"$@\"\n").unwrap();
    let quoted = format!("'{}'", launcher.display());
    for prefix in ["", "bash ", "/bin/bash ", "bash -- "] {
        assert!(check(&format!("{prefix}{quoted} context"), &home), "execution refused: {prefix}{quoted}");
    }
    assert!(check(&format!("bash {quoted} create --title 'Capture follow-up'"), &home));
    for text in [
        format!("bash {quoted} context > {quoted}"),
        format!("bash {quoted} context; rm {quoted}"),
        format!("bash {quoted} context && printf bad > {quoted}"),
        format!("bash -c {quoted}"),
        format!("bash '{}/other.sh' context", managed.display()),
        format!("python3 {quoted}"),
        format!("sed -i '' s/a/b/ {quoted}"),
        format!("bash {quoted} context\nrm {quoted}"),
    ] {
        assert!(!check(&text, &home), "artifact mutation or unsupported execution allowed: {text}");
    }
}

